# Generates Julia enum / error-code tables from the HBM QuantumX SDK headers.
#
#   julia gen/generate.jl [path/to/QuantumX Low-level API]
#
# Output: src/generated/enums.jl and src/generated/errors.jl
# Re-run only when the SDK headers change. The generated files are checked in.

const SDK = length(ARGS) >= 1 ? ARGS[1] : normpath(joinpath(@__DIR__, "..", "..", "QuantumX Low-level API"))
const OUT = joinpath(@__DIR__, "..", "src", "generated")

const HEADERS = ["TypeDef.h", "DaqDefs.h", "CanDrvInterface.h", "DSS_FrameDefs.h", "HBM_QX_Framework.h"]

# Headers are Windows-1252; only ASCII matters for identifiers/values.
readlatin1(path) = filter(!=(Char(13)), String(map(b -> b < 0x80 ? Char(b) : Char(63), read(path))))

function strip_comments(s)
    # single left-to-right pass so "//***" lines don't open a block comment
    return replace(s, r"//[^\n]*|/\*.*?\*/"s => " ")
end

# enums we expose as plain constants (bit masks / huge error table)
const FLAG_ENUMS = Set(["enComLogSrc", "enDbgLogSrc", "enErrlogLevel", "tErrStatLevel"])
const SKIP_ENUMS = Set(["tError", "tHBM_BOOL"])

const values = Dict{String,Int64}()   # every known integer symbol (macros + enumerators)

function evalexpr(expr::AbstractString)
    e = strip(expr)
    e = replace(e, r"static_cast<[^>]*>" => "")
    e = replace(e, r"\b(\d+)[uUlL]+\b" => s"\1")
    # substitute known identifiers
    e = replace(e, r"\b0[xX][0-9a-fA-F]+\b|[A-Za-z_]\w*" => function (id)
        occursin(r"^0[xX]", id) && return id
        haskey(values, id) ? string(values[id]) : error("unknown identifier $id in '$expr'")
    end)
    occursin(r"^[0-9a-fA-FxX\s\|\(\)\+\-<>&~]+$", e) || error("unsupported expression '$expr'")
    v = eval(Meta.parse(e))
    return Int64(v)
end

function collect_defines!(src)
    for m in eachmatch(r"^[ \t]*#define[ \t]+([A-Za-z_]\w*)[ \t]+([^\n]+)$"m, src)
        name, val = m.captures
        val = strip(replace(val, r"//.*" => ""))
        try
            values[name] = evalexpr(val)
        catch
        end
    end
end

struct CEnum
    name::String
    items::Vector{Pair{String,Int64}}
end

function parse_enums(src)
    enums = CEnum[]
    for m in eachmatch(r"\benum\s+(\w+)\s*\{(.*?)\}"s, src)
        name, body = m.captures
        items = Pair{String,Int64}[]
        next = 0
        for part in split(body, ',')
            p = strip(part)
            isempty(p) && continue
            if occursin('=', p)
                k, v = strip.(split(p, '='; limit=2))
                val = evalexpr(v)
            else
                k, val = p, next
            end
            push!(items, String(k) => val)
            values[String(k)] = val
            next = val + 1
        end
        push!(enums, CEnum(name, items))
    end
    return enums
end

const RENAME = Dict("enFormat" => "DaqFormat")
juliatypename(n) = haskey(RENAME, n) ? RENAME[n] : startswith(n, "en") ? n[3:end] : (startswith(n, "t") ? n[2:end] : n)

function main()
    srcs = Dict(h => strip_comments(readlatin1(joinpath(SDK, h))) for h in HEADERS)
    values["ENUM_UNKNOWN"] = 0xFFFF
    for h in HEADERS
        collect_defines!(srcs[h])
    end
    enums = CEnum[]
    errors = Pair{String,Int64}[]
    for h in HEADERS
        for e in parse_enums(srcs[h])
            if e.name == "tError"
                append!(errors, e.items)
            elseif !(e.name in SKIP_ENUMS)
                push!(enums, e)
            end
        end
    end
    mkpath(OUT)

    open(joinpath(OUT, "enums.jl"), "w") do io
        println(io, "# AUTO-GENERATED by gen/generate.jl from the HBM QuantumX SDK headers. Do not edit.\n")
        names = String[]
        for e in enums
            vals = last.(e.items)
            dup = length(unique(vals)) != length(vals)
            base = any(<(0), vals) ? "Int32" : (maximum(vals) > typemax(Int32) ? "UInt32" : "Int32")
            if e.name in FLAG_ENUMS || dup
                println(io, "# C enum ", e.name, " (exposed as constants)")
                for (k, v) in e.items
                    println(io, "const ", k, " = ", base == "UInt32" || v >= 0 ? "UInt32($v)" : "Int32($v)")
                    push!(names, k)
                end
            else
                jn = juliatypename(e.name)
                println(io, "\"C enum `", e.name, "`\"")
                println(io, "@enum ", jn, "::", base, " begin")
                for (k, v) in e.items
                    println(io, "    ", k, " = ", v)
                end
                println(io, "end")
                push!(names, jn)
                append!(names, first.(e.items))
            end
            println(io)
        end
        println(io, "const GENERATED_ENUM_NAMES = Symbol[", join((":" * n for n in names), ", "), "]")
    end

    open(joinpath(OUT, "errors.jl"), "w") do io
        println(io, "# AUTO-GENERATED by gen/generate.jl from DSS_FrameDefs.h (enum tError). Do not edit.\n")
        println(io, "const ERROR_NAMES = Dict{Int32,Symbol}(")
        seen = Set{Int64}()
        for (k, v) in errors
            v in seen && continue   # keep first name for duplicated codes
            push!(seen, v)
            println(io, "    Int32($v) => :", k, ",")
        end
        println(io, ")\n")
        for (k, v) in errors
            println(io, "const ", k, " = Int32($v)")
        end
    end
    println("Generated $(length(enums)) enums and $(length(errors)) error codes into $OUT")
end

main()
